// Types mirroring the backend /api/chat contract (README "API", NOTES P-053/P-059).
// Shared JSON fixtures in src/test/fixtures are generated by the backend and type-checked here.

export type SourceType = 'public_api' | 'public_dataset_snapshot' | 'recorded_api_fallback'

export type Provenance = {
  source_type: SourceType
  name: string
  url: string
  retrieval_method: string
  retrieved_at: string
  observation_period: string
  limitations: string[]
  cache_status: string | null
}

export type MetricValue = {
  metric: string
  value: number | null
  numerator: number | null
  denominator: number | null
  window: string | null
  missing_reason: string | null
  flags: string[]
}

export type SmallSample = {
  airport: string
  eligible_departures: number
  threshold: number
  period: string
  affected_metrics: string[]
}

export type Envelope<T, R extends string> = {
  result_type: R
  data: T
  provenance: Provenance[]
  windows: Record<string, string>
  definitions: Record<string, string>
  warnings: string[]
  coverage_notes: string[]
  confidence: 'high' | 'medium' | 'low'
  formula_version: string | null
}

export type KpiContribution = { raw: number | null; normalized: number | null; weight: number; contribution: number | null }

export type RankingData = {
  status: 'ranked' | 'not_ranked'
  reason: string | null
  airports: {
    airport: string
    status: 'ranked' | 'insufficient_data' | 'not_ranked'
    rank: number | null
    score: number | null
    coverage: number
    flags: string[]
    kpis: Record<string, KpiContribution>
  }[]
  weights_used: Record<string, number>
  ranges: { metric: string; weight: number; low: number | null; high: number | null; n_values: number; usable: boolean; note: string | null }[]
  warnings: string[]
  rank_changes: Record<string, number>
  interpretation: string
  candidate_group: {
    query: string | string[]
    interpretation: string
    airports: string[]
    hub_classes: Record<string, string | null>
    eligibility: string | null
    hub_filter: { hub_classes: string[]; excluded_airports: string[] } | null
  }
  metric_details: Record<string, Record<string, MetricValue>>
  small_sample_airports: SmallSample[]
}

export type ComparisonData = {
  airports: string[]
  metrics: string[]
  values: Record<string, Record<string, MetricValue>>
  differences: Record<string, Record<string, { absolute: number | null; relative: number | null }>>
  baseline: string
  small_sample_airports: SmallSample[]
}

export type Share = { service_classes: string[]; numerator: number; denominator: number; share: number | null; missing_reason: string | null }

export type LongHaulData = {
  origin: string
  threshold_miles: number
  primary: Share
  all_classes: Share
  by_class: Record<string, { departures: number; long_haul_departures: number }>
  distance_bands: Record<string, { selected_classes: number; all_classes: number }>
  definition: string
  notes: string[]
}

export type PeerPosition = { value: number | null; peers_with_data: number; percentile: number | null; rank_desc: number | null }

export type DemandProfileData = {
  airport: string
  peer_group: string
  peers: string[]
  observed_demand: Record<string, MetricValue & { t12m_vs_2019?: number | null }>
  capacity_pressure: Record<string, PeerPosition>
  delay_causes: { cause: string; minutes: number; share: number }[] | null
  unmet_demand: { measured: false; statement: string }
  subject_metrics: Record<string, MetricValue>
  small_sample_airports: SmallSample[]
}

export type AirportsData = {
  query: string
  kind: 'airport' | 'region'
  interpretation: string
  eligibility: string | null
  airports: { code: string; name: string; city: string; state: string; faa_region: string; hub: string; primary: boolean }[]
  truncated: boolean
}

export type MetricsData = {
  metrics: { id: string; label: string; formula: string; unit: string; source: string; category: string; rankable: boolean }[]
}

export type Artifact =
  | Envelope<RankingData, 'ranking'>
  | Envelope<ComparisonData, 'comparison'>
  | Envelope<LongHaulData, 'long_haul'>
  | Envelope<DemandProfileData, 'demand_profile'>
  | Envelope<AirportsData, 'airports'>
  | Envelope<MetricsData, 'metrics'>

export type EvidenceItem = {
  tool: string
  tool_call_id?: string
  input?: Record<string, unknown> | null
  status: 'success' | 'error'
  artifact: Artifact | null
  error?: string
}

export type ChatStatus = 'complete' | 'completed_with_tool_errors' | 'incomplete'

export type ChatResponse = {
  session_id: string
  mode: 'agent'
  status: ChatStatus
  reply_markdown: string
  evidence: EvidenceItem[]
  sources: Provenance[]
  warnings: string[]
  errors: string[]
  incomplete: boolean
  notice: string | null
}

export type DemoResponse = {
  mode: 'demo'
  label: string
  scenario: string
  question: string
  caption: string
  evidence: EvidenceItem[]
  sources: Provenance[]
  warnings: string[]
}

export type BtsApiStatus = {
  reachable: boolean
  status_code?: number
  latest_month?: string | null
  source_type: 'public_api'
  url: string
  retrieved_at: string
  error?: string
}

export type HealthResponse = {
  status: string
  llm_configured: boolean
  llm_model: string
  bts_api: BtsApiStatus
}
